contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _seq, bytes32 _batcher, uint256 _overhead, uint256 _scalar) public payable {
        string memory v1 = c.version();
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _seq, _batcher, _overhead, _scalar) {
            reverted = false;
        } catch {
            reverted = true;
        }
        string memory v2 = c.version();
        assert(keccak256(bytes(v1)) == keccak256(bytes("1.0.0")) && keccak256(bytes(v2)) == keccak256(bytes("1.0.0")));
    }
    receive() external payable {}
}

